SELECT t.troponin_i_value, COUNT(t.troponin_i_value) AS count, CAST(COUNT(t.troponin_i_value) AS FLOAT) / NULLIF((SELECT COUNT(DISTINCT p.subject_id) FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 76 AND 86 AND a.admission_type_id = 1), 0) AS proportion, AVG(t.troponin_i_value) AS average, MEDIAN(t.troponin_i_value) AS median, (percentile_cont(0.75) within GROUP (ORDER BY t.troponin_i_value) - percentile_cont(0.25) within GROUP (ORDER BY t.troponin_i_value)) AS interquartile_range FROM troponin_i t JOIN labevents l ON t.labevent_id = l.labevent_id WHERE l.itemid = 787975 AND l.value <= 0.04 GROUP BY t.troponin_i_value ORDER BY t.troponin_i_value NULLS LAST;